2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	import org.springframework.web.bind.annotation.RequestParam;
6	import net.officefloor.web.ObjectResponse;
7	
8	/**
9	 * {@code GET /api/invoices/summary?invoiceId=<id>} — the money breakdown for one invoice: its
10	 * subtotal (the worked-out sum of its line items, Flyway V13/V14, kept in the amount column), the
11	 * percentage discount taken off it (Flyway V27), the discount in money, and the final total
12	 * (subtotal minus discount). The figures are worked out on the server so the money math lives in one
13	 * place; an invoice with no discount simply bills its full subtotal. Wired by
14	 * {@code officefloor/rest/api/invoices/summary.GET.yml}.
15	 */
16	public class InvoiceSummaryGetLogic {
17	
18	    public void service(@RequestParam("invoiceId") Long invoiceId, InvoiceRepository invoices,
19	            ObjectResponse<InvoiceSummaryView> response) {
20	        Invoice invoice = invoices.findById(invoiceId).orElse(null);
21	        BigDecimal subtotal = invoice != null ? invoice.getAmount() : BigDecimal.ZERO;
22	        BigDecimal discountPct = invoice != null && invoice.getDiscountPct() != null
23	                ? invoice.getDiscountPct()
24	                : BigDecimal.ZERO;
25	        // Discount in money, rounded to whole cents; the final total is the subtotal less that.
